var app = WebApplication.Create(args);
var buecher = new Dictionary<int, Buch>
  { [1] = new Buch(1, "Faust") };

var api = app.MapGroup("/api/v1/buecher");
api.MapGet("/", () => buecher.Values);
api.MapGet("/{id:int}", (int id) =>
  buecher.TryGetValue(id, out var b)
    ? Results.Ok(b)
    : Results.NotFound(
        new { error = "nicht gefunden" }));
api.MapPost("/", (NeuesBuch neu) =>
{
  if (string.IsNullOrWhiteSpace(neu.Titel))
    return Results.BadRequest(
      new { error = "titel fehlt" });
  int id = buecher.Keys.DefaultIfEmpty()
                       .Max() + 1;
  var b = new Buch(id, neu.Titel);
  buecher[id] = b;
  return Results.Created(
    $"/api/v1/buecher/{id}", b);
});

app.Run("http://127.0.0.1:5000");

record Buch(int Id, string Titel);
record NeuesBuch(string? Titel);

$ curl http://127.0.0.1:5000/api/v1/buecher/1
{"id":1,"titel":"Faust"}

$ curl -X POST -d '{"titel":"Woyzeck"}' \
  -H "Content-Type: application/json" \
  http://127.0.0.1:5000/api/v1/buecher
{"id":2,"titel":"Woyzeck"}

using System.Net.Http.Json;

using var http = new HttpClient {
  BaseAddress =
    new Uri("http://127.0.0.1:5000/api/v1/"),
  Timeout = TimeSpan.FromSeconds(5) };

var alle = await http
  .GetFromJsonAsync<List<Buch>>("buecher");
Console.WriteLine(alle!.Count);   // 1

var resp = await http.PostAsJsonAsync(
  "buecher", new { titel = "Ödipus" });
var neu = await resp.Content
  .ReadFromJsonAsync<Buch>();
Console.WriteLine(
  $"{(int)resp.StatusCode} {neu}");
// 201 Buch { Id = 2, Titel = Ödipus }

var r404 = await http.GetAsync("buecher/99");
Console.WriteLine(r404.StatusCode);
// NotFound
try { r404.EnsureSuccessStatusCode(); }
catch (HttpRequestException e)
{ Console.WriteLine(e.StatusCode); }
// NotFound

record Buch(int Id, string Titel);
